/**
 * Données simplifiées des emojis avec leurs coordonnées dans le sprite sheet
 * Basé sur le format utilisé par Mattermost
 */

// Définition du type d'emoji
export interface EmojiData {
  name: string;
  unified: string;
  short_name: string;
  short_names: string[];
  sheet_x: number;
  sheet_y: number;
  category: string;
  subcategory?: string;
  emoji?: string;
  text?: string;
}

